.darma-loader-darma-b16-scissor-lift-rise .darma-loader-darma-b16-scissor-lift-rise__rig span:nth-of-type(2) { bottom: 4%; animation-name: darma-loader-darma-b16-scissor-lift-rise-scissor-arm-mirror; }
