.darma-loader-darma-b16-scissor-lift-rise .darma-loader-darma-b16-scissor-lift-rise__rig span:nth-of-type(4) { bottom: 30%; animation-name: darma-loader-darma-b16-scissor-lift-rise-scissor-arm-mirror; }
